SELECT c.conname,c.conrelid::regclass::text AS child_table,c.confrelid::regclass::text AS parent_table,pg_get_constraintdef(c.oid) AS definition FROM pg_constraint c WHERE c.contype='f' AND (c.confrelid IN ('public."SSP_Facility_Booking"'::regclass,'public."SSP_Facility_Booking_Request"'::regclass) OR c.conrelid IN ('public."SSP_Facility_Booking"'::regclass,'public."SSP_Facility_Booking_Request"'::regclass));
